def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_moves = []
    opp_moves = []
    for h in history:
        my_moves.append(h[0])
        opp_moves.append(h[1])

    my_def_count = 0
    opp_def_count = 0
    for m in my_moves:
        if m == 'D':
            my_def_count += 1
    for o in opp_moves:
        if o == 'D':
            opp_def_count += 1

    last_my = my_moves[-1]
    last_opp = opp_moves[-1]

    unprovoked_def = 0
    if opp_moves[0] == 'D':
        unprovoked_def += 1
    for i in range(1, n):
        if opp_moves[i] == 'D' and my_moves[i-1] == 'C':
            unprovoked_def += 1

    # Exploit unconditional cooperators
    if opp_def_count == 0:
        if my_def_count >= 3:
            return 'D'
        if n in (5, 10, 15) and last_my == 'C':
            return 'D'
        return 'C'

    # Heavy defector
    if opp_def_count > n * 0.8:
        return 'D'

    # Endgame logic
    if n >= 99:
        return 'D'
    if n >= 95:
        if unprovoked_def > 0:
            return 'D'
        if n == 98:
            return 'C'

    # Main reciprocal strategy
    if last_opp == 'C':
        return 'C'
    else:
        if unprovoked_def > 0:
            return 'D'
        provoked = False
        start = max(0, n - 3)
        for i in range(start, n - 1):
            if my_moves[i] == 'D':
                provoked = True
                break
        if provoked:
            return 'C'
        else:
            if opp_def_count * 4 < n and rng.random() < 0.25:
                return 'C'
            return 'D'
